                    float ar1 = As[ty * MR + 1][k];
                    float ar2 = As[ty * MR + 2][k];
                    float ar3 = As[ty * MR + 3][k];
                    float ar4 = As[ty * MR + 4][k];
                    float ar5 = As[ty * MR + 5][k];
                    float ar6 = As[ty * MR + 6][k];
                    float ar7 = As[ty * MR + 7][k];

                    a00 += ar0 * Bs[k][tx * NR + 0];
