                    // stale data from previous iterations being read.
                    // Zero only the elements we might not have written.
                    // Since ty≥2 writes are OOB and skipped, we zero here.
                    #pragma unroll
                    for (int j = 0; j < NR; ++j) {
                        Bs[si % MK][tx * NR + j] = 0.0f;
                    }
                    continue;
                }
                #pragma unroll
                for (int j = 0; j < NR; ++j) {
                    const int bCol = cBase + j;
                    if (bRow < N && bCol < N && bRow >= 0 && bCol >= 0)
