                a30 += ar3 * bk0; a31 += ar3 * bk1; a32 += ar3 * bk2; a33 += ar3 * bk3;
                a34 += ar3 * bk4; a35 += ar3 * bk5; a36 += ar3 * bk6; a37 += ar3 * bk7;
                a40 += ar4 * bk0; a41 += ar4 * bk1; a42 += ar4 * bk2; a43 += ar4 * bk3;
                a44 += ar4 * bk4; a45 += ar4 * bk5; a46 += ar4 * bk6; a47 += ar4 * bk7;
                a50 += ar5 * bk0; a51 += ar5 * bk1; a52 += ar5 * bk2; a53 += ar5 * bk3;
                a54 += ar5 * bk4; a55 += ar5 * bk5; a56 += ar5 * bk6; a57 += ar5 * bk7;
                a60 += ar6 * bk0; a61 += ar6 * bk1; a62 += ar6 * bk2; a63 += ar6 * bk3;
                a64 += ar6 * bk4; a65 += ar6 * bk5; a66 += ar6 * bk6; a67 += ar6 * bk7;
                a70 += ar7 * bk0; a71 += ar7 * bk1; a72 += ar7 * bk2; a73 += ar7 * bk3;
                a74 += ar7 * bk4; a75 += ar7 * bk5; a76 += ar7 * bk6; a77 += ar7 * bk7;
            }

            __syncthreads();
        }
    }

    // ---- Store ----
    #pragma unroll
    for (int i = 0; i < MR; ++i) {
        #pragma unroll
        for (int j = 0; j < NR; ++j) {
            const int r = rBase + i;
            const int c = cBase + j;
            if (r < N && c < N) {
                switch (i * NR + j) {
                    case  0: C[r * N + c]     = a00; break;
                    case  1: C[r * N + c + 1] = a01; break;
                    case  2: C[r * N + c + 2] = a02; break;
                    case  3: C[r * N + c + 3] = a03; break;
                    case  4: C[r * N + c + 4] = a04; break;
                    case  5: C[r * N + c + 5] = a05; break;
                    case  6: C[r * N + c + 6] = a06; break;
                    case  7: C[r * N + c + 7] = a07; break;
                    case  8: C[(r+1) * N + c]     = a10; break;
                    case  9: C[(r+1) * N + c + 1] = a11; break;
                    case 10: C[(r+1) * N + c + 2] = a12; break;
                    case 11: C[(r+1) * N + c + 3] = a13; break;
                    case 12: C[(r+1) * N + c + 4] = a14; break;
                    case 13: C[(r+1) * N + c + 5] = a15; break;
                    case 14: C[(r+1) * N + c + 6] = a16; break;
                    case 15: C[(r+1) * N + c + 7] = a17; break;
                    case 16: C[(r+2) * N + c]     = a20; break;
                    case 17: C[(r+2) * N + c + 1] = a21; break;
                    case 18: C[(r+2) * N + c + 2] = a22; break;
                    case 19: C[(r+2) * N + c + 3] = a23; break;
                    case 20: C[(r+2) * N + c + 4] = a24; break;
                    case 21: C[(r+2) * N + c + 5] = a25; break;
                    case 22: C[(r+2) * N + c + 6] = a26; break;
                    case 23: C[(r+2) * N + c + 7] = a27; break;
                    case 24: C[(r+3) * N + c]     = a30; break;
                    case 25: C[(r+3) * N + c + 1] = a31; break;
                    case 26: C[(r+3) * N + c + 2] = a32; break;
                    case 27: C[(r+3) * N + c + 3] = a33; break;
                    case 28: C[(r+3) * N + c + 4] = a34; break;
                    case 29: C[(r+3) * N + c + 5] = a35; break;
                    case 30: C[(r+3) * N + c + 6] = a36; break;
                    case 31: C[(r+3) * N + c + 7] = a37; break;
                    case 32: C[(r+4) * N + c]     = a40; break;
                    case 33: C[(r+4) * N + c + 1] = a41; break;
                    case 34: C[(r+4) * N + c + 2] = a42; break;
                    case 35: C[(r+4) * N + c + 3] = a43; break;
                    case 36: C[(r+4) * N + c + 4] = a44; break;
                    case 37: C[(r+4) * N + c + 5] = a45; break;
                    case 38: C[(r+4) * N + c + 6] = a46; break;
                    case 39: C[(r+4) * N + c + 7] = a47; break;
                    case 40: C[(r+5) * N + c]     = a50; break;
                    case 41: C[(r+5) * N + c + 1] = a51; break;
