                    case 45: C[(r+5) * N + c + 5] = a55; break;
                    case 46: C[(r+5) * N + c + 6] = a56; break;
                    case 47: C[(r+5) * N + c + 7] = a57; break;
                    case 48: C[(r+6) * N + c]     = a60; break;
                    case 49: C[(r+6) * N + c + 1] = a61; break;
                    case 50: C[(r+6) * N + c + 2] = a62; break;
                    case 51: C[(r+6) * N + c + 3] = a63; break;
                    case 52: C[(r+6) * N + c + 4] = a64; break;
                    case 53: C[(r+6) * N + c + 5] = a65; break;
                    case 54: C[(r+6) * N + c + 6] = a66; break;
                    case 55: C[(r+6) * N + c + 7] = a67; break;
                    case 56: C[(r+7) * N + c]     = a70; break;
                    case 57: C[(r+7) * N + c + 1] = a71; break;
