    if (rowBase+1 < N && colBase   < N) C[(rowBase+1) * N + colBase    ] = a10;
    if (rowBase+1 < N && colBase + 1 < N) C[(rowBase+1) * N + colBase + 1] = a11;
    if (rowBase+1 < N && colBase + 2 < N) C[(rowBase+1) * N + colBase + 2] = a12;
    if (rowBase+1 < N && colBase + 3 < N) C[(rowBase+1) * N + colBase + 3] = a13;
    if (rowBase+2 < N && colBase   < N) C[(rowBase+2) * N + colBase    ] = a20;
    if (rowBase+2 < N && colBase + 1 < N) C[(rowBase+2) * N + colBase + 1] = a21;
    if (rowBase+2 < N && colBase + 2 < N) C[(rowBase+2) * N + colBase + 2] = a22;
