    const int ty  = threadIdx.y;   // 0..7
    const int bR  = blockIdx.y;
    const int bC  = blockIdx.x;

    int rowBase = bR * TILE + ty * MR;   // 8 rows per ty-group
    int colBase = bC * TILE + tx * NR;   // 4 cols per tx-group

