    float a00=0, a01=0, a02=0, a03=0;
    float a10=0, a11=0, a12=0, a13=0;
    float a20=0, a21=0, a22=0, a23=0;
    float a30=0, a31=0, a32=0, a33=0;
    float a40=0, a41=0, a42=0, a43=0;
    float a50=0, a51=0, a52=0, a53=0;
    float a60=0, a61=0, a62=0, a63=0;
    float a70=0, a71=0, a72=0, a73=0;

    const int numSteps = (N + TILE - 1) / TILE;

    for (int t = 0; t < numSteps; ++t) {
        const int baseK = t * TILE;

        for (int mk = 0; mk < TILE; mk += MK) {
            // ---- Load A (TILE rows × MK cols) ----
            // 16 tx × 2 cols = MK=32  |  8 ty × 8 rows = TILE=64
            {
                const int aCol0 = baseK + mk + tx * 2;
                #pragma unroll
                for (int i = 0; i < MR; ++i) {
                    int aRow = rowBase + i;
                    #pragma unroll
                    for (int j = 0; j < 2; ++j) {
                        As[ty * MR + i][tx * 2 + j] =
                            (aRow < N && aCol0 + j < N) ?
                            A[aRow * N + aCol0 + j] : 0.0f;
                    }
                }
            }

            // ---- Load B (MK rows × TILE cols) ----
            // MK/MR = 4 ty groups (ty=0..3) for Bs rows
            {
                const int bRowBase = baseK + mk;
                #pragma unroll
                for (int i = 0; i < MR; ++i) {
                    int bRow = bRowBase + ty * MR + i;
                    int si = ty * MR + i;
                    if (si >= MK) continue;
                    #pragma unroll
                    for (int j = 0; j < NR; ++j) {
                        Bs[si][tx * NR + j] =
                            (bRow < N && colBase + j < N) ?
                            B[bRow * N + colBase + j] : 0.0f;
                    }
                }
            }

