                    case 18: C[(r+4)*N+c + 2] = a42; break;
                    case 19: C[(r+4)*N+c + 3] = a43; break;
                    case 20: C[(r+5)*N+c]     = a50; break;
                    case 21: C[(r+5)*N+c + 1] = a51; break;
                    case 22: C[(r+5)*N+c + 2] = a52; break;
                    case 23: C[(r+5)*N+c + 3] = a53; break;
                    case 24: C[(r+6)*N+c]     = a60; break;
                    case 25: C[(r+6)*N+c + 1] = a61; break;
                    case 26: C[(r+6)*N+c + 2] = a62; break;
                    case 27: C[(r+6)*N+c + 3] = a63; break;
