#include "gemm.cuh"

#include <cuda_runtime.h>

// ---------------------------------------------------------------------------
// TILE 128 × 128 output tile, MK 16 register-blocking step.
// 16×16 block (256 threads) → 64 output elements/thread (8×8).
//
// As[128][MK]  128 output rows × MK k-steps
// Bs[MK][128]  MK k-steps       × 128 output cols
// Shared memory: 8 KiB + 8 KiB = 16 KiB per step
// ---------------------------------------------------------------------------

#define TILE 128
#define MK   16
#define MR    8
#define NR    8

__shared__ float As[TILE][MK];
__shared__ float Bs[MK][TILE];

__global__ void gemmKernel(const float* __restrict__ A,
                           const float* __restrict__ B,
                           float* __restrict__ C,
                           int N)
{
    const int tx = threadIdx.x;
    const int ty = threadIdx.y;
    const int bR = blockIdx.y;
    const int bC = blockIdx.x;

    const int rBase = bR * TILE + ty * MR;
    const int cBase = bC * TILE + tx * NR;

    // 8×8 = 64 accumulators
    float a00=0,a01=0,a02=0,a03=0,a04=0,a05=0,a06=0,a07=0;
    float a10=0,a11=0,a12=0,a13=0,a14=0,a15=0,a16=0,a17=0;
    float a20=0,a21=0,a22=0,a23=0,a24=0,a25=0,a26=0,a27=0;
    float a30=0,a31=0,a32=0,a33=0,a34=0,a35=0,a36=0,a37=0;
    float a40=0,a41=0,a42=0,a43=0,a44=0,a45=0,a46=0,a47=0;
    float a50=0,a51=0,a52=0,a53=0,a54=0,a55=0,a56=0,a57=0;
    float a60=0,a61=0,a62=0,a63=0,a64=0,a65=0,a66=0,a67=0;
    float a70=0,a71=0,a72=0,a73=0,a74=0,a75=0,a76=0,a77=0;

    const int numSteps = (N + TILE - 1) / TILE;

    for (int t = 0; t < numSteps; ++t) {
        const int baseK = t * TILE;

        for (int mk = 0; mk < TILE; mk += MK) {
            // ----- Load A tile (128 rows × MK cols) -----
            // Each thread gets 8 rows, 1 column (MK=16 cols / 16 tx = 1)
            #pragma unroll
            for (int i = 0; i < MR; ++i) {
                const int aRow = rBase + i;
                const int aCol = baseK + mk + tx;
                As[ty * MR + i][tx] =
                    (aRow < N && aCol < N && aRow >= 0 && aCol >= 0) ?
                    A[aRow * N + aCol] : 0.0f;
            }

            // ----- Load B tile (MK rows × 128 cols) -----
            // Each thread gets MK rows, 8 cols
            // Only rows 0..MK-1 fit in Bs[MK][TILE]
            // ty=0 → rows 0..7, ty=1 → rows 8..15, ty≥2 → OOB
            #pragma unroll
            for (int i = 0; i < MR; ++i) {
                const int bRow = baseK + mk + ty * MR + i;
                int si = ty * MR + i;
                // Guard: si < MK required for valid Bs access
                bool ok = (si >= 0 && si < MK);
                if (!ok) {
                    // Still need to zero out the shared memory to avoid
                    // stale data from previous iterations being read.
                    // Zero only the elements we might not have written.
                    // Since ty≥2 writes are OOB and skipped, we zero here.
                    #pragma unroll
                    for (int j = 0; j < NR; ++j) {
                        Bs[si % MK][tx * NR + j] = 0.0f;
                    }
                    continue;
                }
                #pragma unroll
                for (int j = 0; j < NR; ++j) {
                    const int bCol = cBase + j;
                    if (bRow < N && bCol < N && bRow >= 0 && bCol >= 0)
                        Bs[si][tx * NR + j] = B[bRow * N + bCol];
                    else
                        Bs[si][tx * NR + j] = 0.0f;
                }
            }

            __syncthreads();

            // ----- Compute -----
            #pragma unroll
            for (int k = 0; k < MK; ++k) {
                float ar0 = As[ty * MR + 0][k];
                float ar1 = As[ty * MR + 1][k];
                float ar2 = As[ty * MR + 2][k];
                float ar3 = As[ty * MR + 3][k];
                float ar4 = As[ty * MR + 4][k];
                float ar5 = As[ty * MR + 5][k];
                float ar6 = As[ty * MR + 6][k];
                float ar7 = As[ty * MR + 7][k];

                float bk0 = Bs[k][tx * NR + 0];
                float bk1 = Bs[k][tx * NR + 1];
                float bk2 = Bs[k][tx * NR + 2];
                float bk3 = Bs[k][tx * NR + 3];
                float bk4 = Bs[k][tx * NR + 4];
                float bk5 = Bs[k][tx * NR + 5];
                float bk6 = Bs[k][tx * NR + 6];
                float bk7 = Bs[k][tx * NR + 7];

                a00 += ar0 * bk0; a01 += ar0 * bk1; a02 += ar0 * bk2; a03 += ar0 * bk3;
                a04 += ar0 * bk4; a05 += ar0 * bk5; a06 += ar0 * bk6; a07 += ar0 * bk7;
                a10 += ar1 * bk0; a11 += ar1 * bk1; a12 += ar1 * bk2; a13 += ar1 * bk3;
                a14 += ar1 * bk4; a15 += ar1 * bk5; a16 += ar1 * bk6; a17 += ar1 * bk7;
                a20 += ar2 * bk0; a21 += ar2 * bk1; a22 += ar2 * bk2; a23 += ar2 * bk3;
                a24 += ar2 * bk4; a25 += ar2 * bk5; a26 += ar2 * bk6; a27 += ar2 * bk7;
                a30 += ar3 * bk0; a31 += ar3 * bk1; a32 += ar3 * bk2; a33 += ar3 * bk3;
                a34 += ar3 * bk4; a35 += ar3 * bk5; a36 += ar3 * bk6; a37 += ar3 * bk7;
                a40 += ar4 * bk0; a41 += ar4 * bk1; a42 += ar4 * bk2; a43 += ar4 * bk3;
                a44 += ar4 * bk4; a45 += ar4 * bk5; a46 += ar4 * bk6; a47 += ar4 * bk7;
                a50 += ar5 * bk0; a51 += ar5 * bk1; a52 += ar5 * bk2; a53 += ar5 * bk3;
                a54 += ar5 * bk4; a55 += ar5 * bk5; a56 += ar5 * bk6; a57 += ar5 * bk7;
                a60 += ar6 * bk0; a61 += ar6 * bk1; a62 += ar6 * bk2; a63 += ar6 * bk3;
                a64 += ar6 * bk4; a65 += ar6 * bk5; a66 += ar6 * bk6; a67 += ar6 * bk7;
                a70 += ar7 * bk0; a71 += ar7 * bk1; a72 += ar7 * bk2; a73 += ar7 * bk3;
                a74 += ar7 * bk4; a75 += ar7 * bk5; a76 += ar7 * bk6; a77 += ar7 * bk7;
            }

            __syncthreads();
        }
    }

    // ---- Store ----
    #pragma unroll
    for (int i = 0; i < MR; ++i) {
        #pragma unroll
        for (int j = 0; j < NR; ++j) {
            const int r = rBase + i;
            const int c = cBase + j;
            if (r < N && c < N) {
                switch (i * NR + j) {
                    case  0: C[r * N + c]     = a00; break;
                    case  1: C[r * N + c + 1] = a01; break;
                    case  2: C[r * N + c + 2] = a02; break;
                    case  3: C[r * N + c + 3] = a03; break;
                    case  4: C[r * N + c + 4] = a04; break;
                    case  5: C[r * N + c + 5] = a05; break;
                    case  6: C[r * N + c + 6] = a06; break;
                    case  7: C[r * N + c + 7] = a07; break;
                    case  8: C[(r+1) * N + c]     = a10; break;
                    case  9: C[(r+1) * N + c + 1] = a11; break;
                    case 10: C[(r+1) * N + c + 2] = a12; break;
                    case 11: C[(r+1) * N + c + 3] = a13; break;
                    case 12: C[(r+1) * N + c + 4] = a14; break;
                    case 13: C[(r+1) * N + c + 5] = a15; break;
                    case 14: C[(r+1) * N + c + 6] = a16; break;
                    case 15: C[(r+1) * N + c + 7] = a17; break;
                    case 16: C[(r+2) * N + c]     = a20; break;
                    case 17: C[(r+2) * N + c + 1] = a21; break;
                    case 18: C[(r+2) * N + c + 2] = a22; break;
                    case 19: C[(r+2) * N + c + 3] = a23; break;
                    case 20: C[(r+2) * N + c + 4] = a24; break;
                    case 21: C[(r+2) * N + c + 5] = a25; break;
                    case 22: C[(r+2) * N + c + 6] = a26; break;
                    case 23: C[(r+2) * N + c + 7] = a27; break;
                    case 24: C[(r+3) * N + c]     = a30; break;
                    case 25: C[(r+3) * N + c + 1] = a31; break;
                    case 26: C[(r+3) * N + c + 2] = a32; break;
                    case 27: C[(r+3) * N + c + 3] = a33; break;
                    case 28: C[(r+3) * N + c + 4] = a34; break;
                    case 29: C[(r+3) * N + c + 5] = a35; break;
                    case 30: C[(r+3) * N + c + 6] = a36; break;
                    case 31: C[(r+3) * N + c + 7] = a37; break;
                    case 32: C[(r+4) * N + c]     = a40; break;
                    case 33: C[(r+4) * N + c + 1] = a41; break;
                    case 34: C[(r+4) * N + c + 2] = a42; break;
                    case 35: C[(r+4) * N + c + 3] = a43; break;
                    case 36: C[(r+4) * N + c + 4] = a44; break;
                    case 37: C[(r+4) * N + c + 5] = a45; break;
                    case 38: C[(r+4) * N + c + 6] = a46; break;
                    case 39: C[(r+4) * N + c + 7] = a47; break;
                    case 40: C[(r+5) * N + c]     = a50; break;
                    case 41: C[(r+5) * N + c + 1] = a51; break;
                    case 42: C[(r+5) * N + c + 2] = a52; break;
                    case 43: C[(r+5) * N + c + 3] = a53; break;
                    case 44: C[(r+5) * N + c + 4] = a54; break;
                    case 45: C[(r+5) * N + c + 5] = a55; break;
                    case 46: C[(r+5) * N + c + 6] = a56; break;
                    case 47: C[(r+5) * N + c + 7] = a57; break;
                    case 48: C[(r+6) * N + c]     = a60; break;
                    case 49: C[(r+6) * N + c + 1] = a61; break;
                    case 50: C[(r+6) * N + c + 2] = a62; break;
                    case 51: C[(r+6) * N + c + 3] = a63; break;
                    case 52: C[(r+6) * N + c + 4] = a64; break;
                    case 53: C[(r+6) * N + c + 5] = a65; break;
                    case 54: C[(r+6) * N + c + 6] = a66; break;
                    case 55: C[(r+6) * N + c + 7] = a67; break;
                    case 56: C[(r+7) * N + c]     = a70; break;
                    case 57: C[(r+7) * N + c + 1] = a71; break;
                    case 58: C[(r+7) * N + c + 2] = a72; break;
                    case 59: C[(r+7) * N + c + 3] = a73; break;
                    case 60: C[(r+7) * N + c + 4] = a74; break;
                    case 61: C[(r+7) * N + c + 5] = a75; break;
                    case 62: C[(r+7) * N + c + 6] = a76; break;
                    case 63: C[(r+7) * N + c + 7] = a77; break;
                }
            }
        }
    }
}

void launchGemm(const float* dA, const float* dB, float* dC, int N) {
    dim3 block(16, 16);
    dim3 grid((N + TILE - 1) / TILE, (N + TILE - 1) / TILE);
    gemmKernel<<<grid, block>>>(dA, dB, dC, N);
}

