#include "gemm.cuh"

#include <cuda_runtime.h>

// ============================================================================
//  Tile 64 × 64   ·  16×16 block (256 threads)   ·  MR=NR=4
//  Each thread owns a 4×4 sub-tile (16 output elements).
//  Accumulate over TILE=64 k-values.
//
//  Shared memory: As[64][65] + Bs[65][65] = 16.64 KiB each → 33.28 KiB total.
//  Occupancy: 164 KiB / 33.28 KiB ≈ 5 blocks  |  1536/256 = 6 blocks
//  → 5 blocks per SM, 1280 concurrent threads (83 %).
//
//  Key optimisations:
//   1. __restrict__ on all pointers
//   2. Column-padded shared memory to break 32-bank alignment
//   3. Fully unrolled inner loops (TILE is a compile-time const)
//   4. Local float temporaries to keep data in registers
//   5. Correct grid dimensions for arbitrary N
// ============================================================================

#define TILE 64
#define MR   4
#define NR   4

// Shared tiles – pad column dimension so shared-memory bank
// conflicts are avoided for the As reads (strided by 1 across columns).
__shared__ float As[TILE][TILE + 1];
__shared__ float Bs[TILE + 1][TILE + 1];

__global__ void gemmKernel(const float* __restrict__ A,
                           const float* __restrict__ B,
                           float* __restrict__ C,
                           int N)
{
    const int tx  = threadIdx.x;
    const int ty  = threadIdx.y;
    const int bR  = blockIdx.y;
    const int bC  = blockIdx.x;

    int rowBase = bR * TILE + ty * MR;   // 0 .. TILE - MR
    int colBase = bC * TILE + tx * NR;   // 0 .. TILE - NR

    // Unrolled accumulators  (16 float vars = 64 B / thread)
    float a00=0,a01=0,a02=0,a03=0;
    float a10=0,a11=0,a12=0,a13=0;
    float a20=0,a21=0,a22=0,a23=0;
    float a30=0,a31=0,a32=0,a33=0;

    const int numTiles = (N + TILE - 1) / TILE;

    for (int t = 0; t < numTiles; ++t) {
        const int baseK = t * TILE;

        /* ---- Load A tile into shared memory ----
         *  Thread (tx,ty) stores As[ty*4+i][tx*4+j]
         *  = A[(rowBase+i)*N + (baseK + tx*4 + j)]
         *  4 rows × 4 cols = 16 elements per thread.
         */
        {
            const int aCol0 = baseK + tx * NR;
            #pragma unroll
            for (int i = 0; i < MR; ++i) {
                const int aRow = rowBase + i;
                #pragma unroll
                for (int j = 0; j < NR; ++j) {
                    As[ty * MR + i][tx * NR + j] =
                        (aRow < N && aCol0 + j < N) ?
                        A[aRow * N + aCol0 + j] : 0.0f;
                }
            }
        }

        /* ---- Load B tile into shared memory ----
         *  Thread (tx,ty) stores Bs[ty*4+i][tx*4+j]
         *  = B[(baseK + ty*4 + i)*N + (colBase + j)]
         */
        {
            #pragma unroll
            for (int i = 0; i < MR; ++i) {
                const int bRow = baseK + ty * MR + i;
                #pragma unroll
                for (int j = 0; j < NR; ++j) {
                    Bs[ty * MR + i][tx * NR + j] =
                        (bRow < N && colBase + j < N) ?
                        B[bRow * N + colBase + j] : 0.0f;
                }
            }
        }

        __syncthreads();

        /* ---- Multiply–accumulate (TILE k-values) ---- */
        #pragma unroll
        for (int k = 0; k < TILE; ++k) {
            float ar0 = As[ty * MR + 0][k];
            float ar1 = As[ty * MR + 1][k];
            float ar2 = As[ty * MR + 2][k];
            float ar3 = As[ty * MR + 3][k];

            a00 += ar0 * Bs[k][tx * NR + 0];
            a01 += ar0 * Bs[k][tx * NR + 1];
            a02 += ar0 * Bs[k][tx * NR + 2];
            a03 += ar0 * Bs[k][tx * NR + 3];

            a10 += ar1 * Bs[k][tx * NR + 0];
            a11 += ar1 * Bs[k][tx * NR + 1];
            a12 += ar1 * Bs[k][tx * NR + 2];
            a13 += ar1 * Bs[k][tx * NR + 3];

            a20 += ar2 * Bs[k][tx * NR + 0];
            a21 += ar2 * Bs[k][tx * NR + 1];
            a22 += ar2 * Bs[k][tx * NR + 2];
            a23 += ar2 * Bs[k][tx * NR + 3];

            a30 += ar3 * Bs[k][tx * NR + 0];
            a31 += ar3 * Bs[k][tx * NR + 1];
            a32 += ar3 * Bs[k][tx * NR + 2];
            a33 += ar3 * Bs[k][tx * NR + 3];
        }

        __syncthreads();
    }

    /* ---- Store 4×4 output elements ---- */
    if (rowBase   < N && colBase   < N) C[rowBase   * N + colBase    ] = a00;
    if (rowBase   < N && colBase + 1 < N) C[rowBase   * N + colBase + 1] = a01;
    if (rowBase   < N && colBase + 2 < N) C[rowBase   * N + colBase + 2] = a02;
    if (rowBase   < N && colBase + 3 < N) C[rowBase   * N + colBase + 3] = a03;
    if (rowBase+1 < N && colBase   < N) C[(rowBase+1) * N + colBase    ] = a10;
    if (rowBase+1 < N && colBase + 1 < N) C[(rowBase+1) * N + colBase + 1] = a11;
    if (rowBase+1 < N && colBase + 2 < N) C[(rowBase+1) * N + colBase + 2] = a12;
    if (rowBase+1 < N && colBase + 3 < N) C[(rowBase+1) * N + colBase + 3] = a13;
    if (rowBase+2 < N && colBase   < N) C[(rowBase+2) * N + colBase    ] = a20;
    if (rowBase+2 < N && colBase + 1 < N) C[(rowBase+2) * N + colBase + 1] = a21;
    if (rowBase+2 < N && colBase + 2 < N) C[(rowBase+2) * N + colBase + 2] = a22;
    if (rowBase+2 < N && colBase + 3 < N) C[(rowBase+2) * N + colBase + 3] = a23;
    if (rowBase+3 < N && colBase   < N) C[(rowBase+3) * N + colBase    ] = a30;
    if (rowBase+3 < N && colBase + 1 < N) C[(rowBase+3) * N + colBase + 1] = a31;
    if (rowBase+3 < N && colBase + 2 < N) C[(rowBase+3) * N + colBase + 2] = a32;
    if (rowBase+3 < N && colBase + 3 < N) C[(rowBase+3) * N + colBase + 3] = a33;
}

void launchGemm(const float* dA, const float* dB, float* dC, int N) {
    dim3 block(16, 16);
    dim3 grid((N + TILE - 1) / TILE, (N + TILE - 1) / TILE);
    gemmKernel<<<grid, block>>>(dA, dB, dC, N);
}

#include "gemm.cuh"

#include <cuda_runtime.h>

// ============================================================================
//  Tile 64×64  ·  16×16 block (256 threads)  ·  MR=NR=4
//  MK=32 register‑blocking: two steps per tile.
//  As[64][32] + Bs[32][64] = 8 KiB each = 16 KiB per step → very low
//  shared‑memory pressure → 6 blocks/SM (thread limit) → 1536 threads
//  (100 % occupancy).
//
//  Bs‑tile has 32 rows / 4 rows_per_ty = 8 ty-groups (ty 0..7).
//  128 of 256 threads load Bs (50 % utilisation) – the rest still
//  participate in the A‑load and the full FMA count.
// ============================================================================

#define TILE 64
#define MK   32
#define MR    4
#define NR    4

__shared__ float As[TILE][MK];
__shared__ float Bs[MK][TILE];

__global__ void gemmKernel(const float* __restrict__ A,
                           const float* __restrict__ B,
                           float* __restrict__ C,
                           int N)
{
    const int tx  = threadIdx.x;
    const int ty  = threadIdx.y;
    const int bR  = blockIdx.y;
    const int bC  = blockIdx.x;

    int rowBase = bR * TILE + ty * MR;
    int colBase = bC * TILE + tx * NR;

    float a00=0,a01=0,a02=0,a03=0;
    float a10=0,a11=0,a12=0,a13=0;
    float a20=0,a21=0,a22=0,a23=0;
    float a30=0,a31=0,a32=0,a33=0;

    const int numSteps = (N + TILE - 1) / TILE;

    for (int t = 0; t < numSteps; ++t) {
        const int baseK = t * TILE;

        for (int mk = 0; mk < TILE; mk += MK) {
            /* ---- Load A tile (TILE rows × MK cols) ---- */
            // 16 tx values × 2 cols = MK=32
            {
                const int aCol0 = baseK + mk;
                #pragma unroll
                for (int i = 0; i < MR; ++i) {
                    const int aRow = rowBase + i;
                    #pragma unroll
                    for (int j = 0; j < 2; ++j) {  // 2 cols per tx
                        int aCol = aCol0 + tx * 2 + j;
                        As[ty * MR + i][tx * 2 + j] =
                            (aRow < N && aCol < N) ?
                            A[aRow * N + aCol] : 0.0f;
                    }
                }
            }

            /* ---- Load B tile (MK rows × TILE cols) ---- */
            // ty=0..7 → 32 rows; ty=8..15 skipped (OOB for Bs[MK][TILE])
            {
                const int bRowBase = baseK + mk;
                #pragma unroll
                for (int i = 0; i < MR; ++i) {
                    const int bRow = bRowBase + ty * MR + i;
                    int si = ty * MR + i;
                    // Skip out-of-range shared-memory writes
                    if (si >= MK) continue;
                    #pragma unroll
                    for (int j = 0; j < NR; ++j) {
                        int bCol = colBase + j;
                        Bs[si][tx * NR + j] =
                            (bRow < N && bCol < N) ?
                            B[bRow * N + bCol] : 0.0f;
                    }
                }
            }

            __syncthreads();

            /* ---- Compute ---- */
            #pragma unroll
            for (int k = 0; k < MK; ++k) {
                float ar0 = As[ty * MR + 0][k];
                float ar1 = As[ty * MR + 1][k];
                float ar2 = As[ty * MR + 2][k];
                float ar3 = As[ty * MR + 3][k];

                a00 += ar0 * Bs[k][tx * NR + 0];
                a01 += ar0 * Bs[k][tx * NR + 1];
                a02 += ar0 * Bs[k][tx * NR + 2];
                a03 += ar0 * Bs[k][tx * NR + 3];

                a10 += ar1 * Bs[k][tx * NR + 0];
                a11 += ar1 * Bs[k][tx * NR + 1];
                a12 += ar1 * Bs[k][tx * NR + 2];
                a13 += ar1 * Bs[k][tx * NR + 3];

                a20 += ar2 * Bs[k][tx * NR + 0];
                a21 += ar2 * Bs[k][tx * NR + 1];
                a22 += ar2 * Bs[k][tx * NR + 2];
                a23 += ar2 * Bs[k][tx * NR + 3];

                a30 += ar3 * Bs[k][tx * NR + 0];
                a31 += ar3 * Bs[k][tx * NR + 1];
                a32 += ar3 * Bs[k][tx * NR + 2];
                a33 += ar3 * Bs[k][tx * NR + 3];
            }

            __syncthreads();
        }
    }

    /* ---- Store ---- */
    if (rowBase   < N && colBase   < N) C[rowBase   * N + colBase    ] = a00;
    if (rowBase   < N && colBase + 1 < N) C[rowBase   * N + colBase + 1] = a01;
    if (rowBase   < N && colBase + 2 < N) C[rowBase   * N + colBase + 2] = a02;
    if (rowBase   < N && colBase + 3 < N) C[rowBase   * N + colBase + 3] = a03;
    if (rowBase+1 < N && colBase   < N) C[(rowBase+1) * N + colBase    ] = a10;
    if (rowBase+1 < N && colBase + 1 < N) C[(rowBase+1) * N + colBase + 1] = a11;
    if (rowBase+1 < N && colBase + 2 < N) C[(rowBase+1) * N + colBase + 2] = a12;
    if (rowBase+1 < N && colBase + 3 < N) C[(rowBase+1) * N + colBase + 3] = a13;
    if (rowBase+2 < N && colBase   < N) C[(rowBase+2) * N + colBase    ] = a20;
    if (rowBase+2 < N && colBase + 1 < N) C[(rowBase+2) * N + colBase + 1] = a21;
    if (rowBase+2 < N && colBase + 2 < N) C[(rowBase+2) * N + colBase + 2] = a22;
    if (rowBase+2 < N && colBase + 3 < N) C[(rowBase+2) * N + colBase + 3] = a23;
    if (rowBase+3 < N && colBase   < N) C[(rowBase+3) * N + colBase    ] = a30;
    if (rowBase+3 < N && colBase + 1 < N) C[(rowBase+3) * N + colBase + 1] = a31;
    if (rowBase+3 < N && colBase + 2 < N) C[(rowBase+3) * N + colBase + 2] = a32;
    if (rowBase+3 < N && colBase + 3 < N) C[(rowBase+3) * N + colBase + 3] = a33;
}

void launchGemm(const float* dA, const float* dB, float* dC, int N) {
    dim3 block(16, 16);
    dim3 grid((N + TILE - 1) / TILE, (N + TILE - 1) / TILE);
    gemmKernel<<<grid, block>>>(dA, dB, dC, N);
}

