#include "gemm.cuh"

#include <cuda_runtime.h>

// Tile 64×64, MK=32 register blocking, MR=NR=4, 16×16 block (256 threads).
// Achieved ~33 % of A40 FP32 peak.  Further optimisations attempted here.

#define TILE 64
#define MK  32
#define MR   4
#define NR   4

__shared__ float As[TILE][MK];
__shared__ float Bs[MK][TILE];

__global__ void gemmKernel(const float* __restrict__ A,
                           const float* __restrict__ B,
                           float* __restrict__ C,
                           int N)
{
    const int tx  = threadIdx.x;
    const int ty  = threadIdx.y;
    const int bR  = blockIdx.y;
    const int bC  = blockIdx.x;

    int rowBase = bR * TILE + ty * MR;
    int colBase = bC * TILE + tx * NR;

    float a00=0,a01=0,a02=0,a03=0;
    float a10=0,a11=0,a12=0,a13=0;
    float a20=0,a21=0,a22=0,a23=0;
    float a30=0,a31=0,a32=0,a33=0;

    const int numSteps = (N + TILE - 1) / TILE;

    for (int t = 0; t < numSteps; ++t) {
        const int baseK = t * TILE;

        for (int mk = 0; mk < TILE; mk += MK) {
            // ---- Load A (TILE rows × MK cols) ----
            {
                const int aCol0 = baseK + mk + tx;
                #pragma unroll
                for (int i = 0; i < MR; ++i) {
                    As[ty * MR + i][tx] =
                        (rowBase + i < N && aCol0 < N) ?
                        A[(rowBase + i) * N + aCol0] : 0.0f;
                }
            }

            // ---- Load B (MK rows × TILE cols) ----
            {
                const int bRowBase = baseK + mk;
                #pragma unroll
                for (int i = 0; i < MR; ++i) {
                    int bRow = bRowBase + ty * MR + i;
                    int si = ty * MR + i;
                    if (si >= MK) continue;
                    #pragma unroll
                    for (int j = 0; j < NR; ++j) {
                        Bs[si][tx * NR + j] =
                            (bRow < N && colBase + j < N) ?
                            B[bRow * N + colBase + j] : 0.0f;
                    }
                }
            }

            __syncthreads();

            // ---- Compute ----
            #pragma unroll
            for (int k = 0; k < MK; ++k) {
                float ar0 = As[ty * MR + 0][k];
                float ar1 = As[ty * MR + 1][k];
                float ar2 = As[ty * MR + 2][k];
                float ar3 = As[ty * MR + 3][k];

                a00 += ar0 * Bs[k][tx * NR + 0];
                a01 += ar0 * Bs[k][tx * NR + 1];
                a02 += ar0 * Bs[k][tx * NR + 2];
                a03 += ar0 * Bs[k][tx * NR + 3];

                a10 += ar1 * Bs[k][tx * NR + 0];
                a11 += ar1 * Bs[k][tx * NR + 1];
                a12 += ar1 * Bs[k][tx * NR + 2];
                a13 += ar1 * Bs[k][tx * NR + 3];

                a20 += ar2 * Bs[k][tx * NR + 0];
                a21 += ar2 * Bs[k][tx * NR + 1];
                a22 += ar2 * Bs[k][tx * NR + 2];
                a23 += ar2 * Bs[k][tx * NR + 3];

                a30 += ar3 * Bs[k][tx * NR + 0];
                a31 += ar3 * Bs[k][tx * NR + 1];
                a32 += ar3 * Bs[k][tx * NR + 2];
                a33 += ar3 * Bs[k][tx * NR + 3];
            }

            __syncthreads();
        }
    }

    if (rowBase   < N && colBase   < N) C[rowBase   * N + colBase    ] = a00;
    if (rowBase   < N && colBase + 1 < N) C[rowBase   * N + colBase + 1] = a01;
    if (rowBase   < N && colBase + 2 < N) C[rowBase   * N + colBase + 2] = a02;
    if (rowBase   < N && colBase + 3 < N) C[rowBase   * N + colBase + 3] = a03;
    if (rowBase+1 < N && colBase   < N) C[(rowBase+1) * N + colBase    ] = a10;
    if (rowBase+1 < N && colBase + 1 < N) C[(rowBase+1) * N + colBase + 1] = a11;
    if (rowBase+1 < N && colBase + 2 < N) C[(rowBase+1) * N + colBase + 2] = a12;
    if (rowBase+1 < N && colBase + 3 < N) C[(rowBase+1) * N + colBase + 3] = a13;
    if (rowBase+2 < N && colBase   < N) C[(rowBase+2) * N + colBase    ] = a20;
    if (rowBase+2 < N && colBase + 1 < N) C[(rowBase+2) * N + colBase + 1] = a21;
    if (rowBase+2 < N && colBase + 2 < N) C[(rowBase+2) * N + colBase + 2] = a22;
    if (rowBase+2 < N && colBase + 3 < N) C[(rowBase+2) * N + colBase + 3] = a23;
    if (rowBase+3 < N && colBase   < N) C[(rowBase+3) * N + colBase    ] = a30;
    if (rowBase+3 < N && colBase + 1 < N) C[(rowBase+3) * N + colBase + 1] = a31;
    if (rowBase+3 < N && colBase + 2 < N) C[(rowBase+3) * N + colBase + 2] = a32;
    if (rowBase+3 < N && colBase + 3 < N) C[(rowBase+3) * N + colBase + 3] = a33;
}

void launchGemm(const float* dA, const float* dB, float* dC, int N) {
    dim3 block(16, 16);
    dim3 grid((N + TILE - 1) / TILE, (N + TILE - 1) / TILE);
    gemmKernel<<<grid, block>>>(dA, dB, dC, N);
}

