// Tile 96×96  ·  16×16 block (256 threads)  ·  MR=NR=6
// MK=48 register‑blocking: 2 steps per tile.
// As[96][48] + Bs[48][96] = 36 KiB → 4 blocks/SM (1024 threads)

#define TILE 96
#define MK  48
#define MR   6
#define NR   6

__shared__ float As[TILE][MK];
__shared__ float Bs[MK][TILE];

__global__ void gemmKernel(const float* __restrict__ A,
                           const float* __restrict__ B,
                           float* __restrict__ C,
                           int N)
{
    const int tx  = threadIdx.x;
    const int ty  = threadIdx.y;
    const int bR  = blockIdx.y;
    const int bC  = blockIdx.x;

    int rowBase = bR * TILE + ty * MR;
    int colBase = bC * TILE + tx * NR;

    // 6×6 = 36 accumulators
    float a00=0, a01=0, a02=0, a03=0, a04=0, a05=0;
    float a10=0, a11=0, a12=0, a13=0, a14=0, a15=0;
    float a20=0, a21=0, a22=0, a23=0, a24=0, a25=0;
    float a30=0, a31=0, a32=0, a33=0, a34=0, a35=0;
    float a40=0, a41=0, a42=0, a43=0, a44=0, a45=0;
    float a50=0, a51=0, a52=0, a53=0, a54=0, a55=0;

    const int numSteps = (N + TILE - 1) / TILE;

    for (int t = 0; t < numSteps; ++t) {
        const int baseK = t * TILE;

        for (int mk = 0; mk < TILE; mk += MK) {
            // ---- Load A (TILE rows × MK cols) ----
            // 16 tx × 3 cols = MK=48
            {
                const int aCol0 = baseK + mk + tx * 3;
                #pragma unroll
                for (int i = 0; i < MR; ++i) {
                    int aRow = rowBase + i;
                    #pragma unroll
                    for (int j = 0; j < 3; ++j) {
                        As[ty * MR + i][tx * 3 + j] =
                            (aRow < N && aCol0 + j < N) ?
                            A[aRow * N + aCol0 + j] : 0.0f;
                    }
                }
            }

            // ---- Load B (MK rows × TILE cols) ----
            // MK/MR = 48/6 = 8 ty groups for Bs (ty=0..7)
            {
                const int bRowBase = baseK + mk;
                #pragma unroll
                for (int i = 0; i < MR; ++i) {
                    int bRow = bRowBase + ty * MR + i;
                    int si = ty * MR + i;
                    if (si >= MK) continue;
                    #pragma unroll
                    for (int j = 0; j < NR; ++j) {
                        Bs[si][tx * NR + j] =
                            (bRow < N && colBase + j < N) ?
                            B[bRow * N + colBase + j] : 0.0f;
                    }
                }
            }

            __syncthreads();

            // ---- Compute ----
            #pragma unroll
            for (int k = 0; k < MK; ++k) {
                float ar0 = As[ty * MR + 0][k];
                float ar1 = As[ty * MR + 1][k];
                float ar2 = As[ty * MR + 2][k];
                float ar3 = As[ty * MR + 3][k];
                float ar4 = As[ty * MR + 4][k];
                float ar5 = As[ty * MR + 5][k];

                a00 += ar0 * Bs[k][tx * NR + 0];
                a01 += ar0 * Bs[k][tx * NR + 1];
                a02 += ar0 * Bs[k][tx * NR + 2];
                a03 += ar0 * Bs[k][tx * NR + 3];
                a04 += ar0 * Bs[k][tx * NR + 4];
                a05 += ar0 * Bs[k][tx * NR + 5];

                a10 += ar1 * Bs[k][tx * NR + 0];
                a11 += ar1 * Bs[k][tx * NR + 1];
                a12 += ar1 * Bs[k][tx * NR + 2];
                a13 += ar1 * Bs[k][tx * NR + 3];
                a14 += ar1 * Bs[k][tx * NR + 4];
                a15 += ar1 * Bs[k][tx * NR + 5];

                a20 += ar2 * Bs[k][tx * NR + 0];
                a21 += ar2 * Bs[k][tx * NR + 1];
                a22 += ar2 * Bs[k][tx * NR + 2];
                a23 += ar2 * Bs[k][tx * NR + 3];
                a24 += ar2 * Bs[k][tx * NR + 4];
                a25 += ar2 * Bs[k][tx * NR + 5];

                a30 += ar3 * Bs[k][tx * NR + 0];
                a31 += ar3 * Bs[k][tx * NR + 1];
                a32 += ar3 * Bs[k][tx * NR + 2];
                a33 += ar3 * Bs[k][tx * NR + 3];
                a34 += ar3 * Bs[k][tx * NR + 4];
                a35 += ar3 * Bs[k][tx * NR + 5];

                a40 += ar4 * Bs[k][tx * NR + 0];
                a41 += ar4 * Bs[k][tx * NR + 1];
                a42 += ar4 * Bs[k][tx * NR + 2];
                a43 += ar4 * Bs[k][tx * NR + 3];
                a44 += ar4 * Bs[k][tx * NR + 4];
                a45 += ar4 * Bs[k][tx * NR + 5];

                a50 += ar5 * Bs[k][tx * NR + 0];
                a51 += ar5 * Bs[k][tx * NR + 1];
                a52 += ar5 * Bs[k][tx * NR + 2];
                a53 += ar5 * Bs[k][tx * NR + 3];
                a54 += ar5 * Bs[k][tx * NR + 4];
                a55 += ar5 * Bs[k][tx * NR + 5];
            }

            __syncthreads();
        }
    }

    // ---- Store 6×6 ----
    for (int i = 0; i < MR; ++i)
        for (int j = 0; j < NR; ++j) {
            int r = rowBase + i, c = colBase + j;
            if (r < N && c < N) {
                int s = i * NR + j;
                switch (s) {
                    case  0: C[r*N+c]   = a00; break; case  1: C[r*N+c+1] = a01; break;
                    case  2: C[r*N+c+2] = a02; break; case  3: C[r*N+c+3] = a03; break;
                    case  4: C[r*N+c+4] = a04; break; case  5: C[r*N+c+5] = a05; break;
                    case  6: C[(r+1)*N+c]   = a10; break; case  7: C[(r+1)*N+c+1] = a11; break;
                    case  8: C[(r+1)*N+c+2] = a12; break; case  9: C[(r+1)*N+c+3] = a13; break;
                    case 10: C[(r+1)*N+c+4] = a14; break; case 11: C[(r+1)*N+c+5] = a15; break;
                    case 12: C[(r+2)*N+c]   = a20; break; case 13: C[(r+2)*N+c+1] = a21; break;
                    case 14: C[(r+2)*N+c+2] = a22; break; case 15: C[(r+2)*N+c+3] = a23; break;
                    case 16: C[(r+2)*N+c+4] = a24; break; case 17: C[(r+2)*N+c+5] = a25; break;
                    case 18: C[(r+3)*N+c]   = a30; break; case 19: C[(r+3)*N+c+1] = a31; break;
                    case 20: C[(r+3)*N+c+2] = a32; break; case 21: C[(r+3)*N+c+3] = a33; break;
                    case 22: C[(r+3)*N+c+4] = a34; break; case 23: C[(r+3)*N+c+5] = a35; break;
                    case 24: C[(r+4)*N+c]   = a40; break; case 25: C[(r+4)*N+c+1] = a41; break;
                    case 26: C[(r+4)*N+c+2] = a42; break; case 27: C[(r+4)*N+c+3] = a43; break;
                    case 28: C[(r+4)*N+c+4] = a44; break; case 29: C[(r+4)*N+c+5] = a45; break;
                    case 30: C[(r+5)*N+c]   = a50; break; case 31: C[(r+5)*N+c+1] = a51; break;
                    case 32: C[(r+5)*N+c+2] = a52; break; case 33: C[(r+5)*N+c+3] = a53; break;
                    case 34: C[(r+5)*N+c+4] = a54; break; case 35: C[(r+5)*N+c+5] = a55; break;
                }
            }
        }
}

void launchGemm(const float* dA, const float* dB, float* dC, int N) {
    dim3 block(16, 16);
