#include "gemm.cuh"

#include <cuda_runtime.h>

// Tile 64×64  ·  16×8 block (128 threads)  ·  MR=8, NR=4
// MK=32 register-blocking (2 steps per tile).
// Shared memory: As[64][32] + Bs[32][64] = 8 KiB each = 16 KiB/step.
// 164 KiB / 16 KiB = 10 blocks; 1536/128 = 12 → 10 blocks/SM.

#define TILE 64
#define MK  32
#define MR   8
#define NR   4

__shared__ float As[TILE][MK];
__shared__ float Bs[MK][TILE];

__global__ void gemmKernel(const float* __restrict__ A,
                           const float* __restrict__ B,
                           float* __restrict__ C,
                           int N)
{
    const int tx  = threadIdx.x;   // 0..15
    const int ty  = threadIdx.y;   // 0..7
    const int bR  = blockIdx.y;
    const int bC  = blockIdx.x;

    int rowBase = bR * TILE + ty * MR;   // 8 rows per ty-group
    int colBase = bC * TILE + tx * NR;   // 4 cols per tx-group

    // 8×4 = 32 accumulators per thread
    float a00=0, a01=0, a02=0, a03=0;
    float a10=0, a11=0, a12=0, a13=0;
    float a20=0, a21=0, a22=0, a23=0;
    float a30=0, a31=0, a32=0, a33=0;
    float a40=0, a41=0, a42=0, a43=0;
    float a50=0, a51=0, a52=0, a53=0;
    float a60=0, a61=0, a62=0, a63=0;
    float a70=0, a71=0, a72=0, a73=0;

    const int numSteps = (N + TILE - 1) / TILE;

    for (int t = 0; t < numSteps; ++t) {
        const int baseK = t * TILE;

        for (int mk = 0; mk < TILE; mk += MK) {
            // ---- Load A (TILE rows × MK cols) ----
            // 16 tx × 2 cols = MK=32  |  8 ty × 8 rows = TILE=64
            {
                const int aCol0 = baseK + mk + tx * 2;
                #pragma unroll
                for (int i = 0; i < MR; ++i) {
                    int aRow = rowBase + i;
                    #pragma unroll
                    for (int j = 0; j < 2; ++j) {
                        As[ty * MR + i][tx * 2 + j] =
                            (aRow < N && aCol0 + j < N) ?
                            A[aRow * N + aCol0 + j] : 0.0f;
                    }
                }
            }

            // ---- Load B (MK rows × TILE cols) ----
            // MK/MR = 4 ty groups (ty=0..3) for Bs rows
            {
                const int bRowBase = baseK + mk;
                #pragma unroll
                for (int i = 0; i < MR; ++i) {
                    int bRow = bRowBase + ty * MR + i;
                    int si = ty * MR + i;
                    if (si >= MK) continue;
                    #pragma unroll
                    for (int j = 0; j < NR; ++j) {
                        Bs[si][tx * NR + j] =
                            (bRow < N && colBase + j < N) ?
                            B[bRow * N + colBase + j] : 0.0f;
                    }
                }
            }

            __syncthreads();

            // ---- Compute ----
            #pragma unroll
            for (int k = 0; k < MK; ++k) {
                float ar0 = As[ty * MR + 0][k];
                float ar1 = As[ty * MR + 1][k];
                float ar2 = As[ty * MR + 2][k];
                float ar3 = As[ty * MR + 3][k];
                float ar4 = As[ty * MR + 4][k];
                float ar5 = As[ty * MR + 5][k];
                float ar6 = As[ty * MR + 6][k];
                float ar7 = As[ty * MR + 7][k];

                a00 += ar0 * Bs[k][tx * NR + 0];
                a01 += ar0 * Bs[k][tx * NR + 1];
                a02 += ar0 * Bs[k][tx * NR + 2];
                a03 += ar0 * Bs[k][tx * NR + 3];
                a10 += ar1 * Bs[k][tx * NR + 0];
                a11 += ar1 * Bs[k][tx * NR + 1];
                a12 += ar1 * Bs[k][tx * NR + 2];
                a13 += ar1 * Bs[k][tx * NR + 3];
                a20 += ar2 * Bs[k][tx * NR + 0];
                a21 += ar2 * Bs[k][tx * NR + 1];
                a22 += ar2 * Bs[k][tx * NR + 2];
                a23 += ar2 * Bs[k][tx * NR + 3];
                a30 += ar3 * Bs[k][tx * NR + 0];
                a31 += ar3 * Bs[k][tx * NR + 1];
                a32 += ar3 * Bs[k][tx * NR + 2];
                a33 += ar3 * Bs[k][tx * NR + 3];
                a40 += ar4 * Bs[k][tx * NR + 0];
                a41 += ar4 * Bs[k][tx * NR + 1];
                a42 += ar4 * Bs[k][tx * NR + 2];
                a43 += ar4 * Bs[k][tx * NR + 3];
                a50 += ar5 * Bs[k][tx * NR + 0];
                a51 += ar5 * Bs[k][tx * NR + 1];
                a52 += ar5 * Bs[k][tx * NR + 2];
                a53 += ar5 * Bs[k][tx * NR + 3];
                a60 += ar6 * Bs[k][tx * NR + 0];
                a61 += ar6 * Bs[k][tx * NR + 1];
                a62 += ar6 * Bs[k][tx * NR + 2];
                a63 += ar6 * Bs[k][tx * NR + 3];
                a70 += ar7 * Bs[k][tx * NR + 0];
                a71 += ar7 * Bs[k][tx * NR + 1];
                a72 += ar7 * Bs[k][tx * NR + 2];
                a73 += ar7 * Bs[k][tx * NR + 3];
            }

            __syncthreads();
        }
    }

    // ---- Store 8×4 ----
    for (int i = 0; i < MR; ++i)
        for (int j = 0; j < NR; ++j) {
            int r = rowBase + i, c = colBase + j;
            if (r < N && c < N) {
                int s = i * NR + j;
                switch (s) {
                    case  0: C[r*N+c]     = a00; break;
                    case  1: C[r*N+c + 1] = a01; break;
                    case  2: C[r*N+c + 2] = a02; break;
                    case  3: C[r*N+c + 3] = a03; break;
                    case  4: C[(r+1)*N+c]     = a10; break;
                    case  5: C[(r+1)*N+c + 1] = a11; break;
                    case  6: C[(r+1)*N+c + 2] = a12; break;
                    case  7: C[(r+1)*N+c + 3] = a13; break;
                    case  8: C[(r+2)*N+c]     = a20; break;
                    case  9: C[(r+2)*N+c + 1] = a21; break;
                    case 10: C[(r+2)*N+c + 2] = a22; break;
                    case 11: C[(r+2)*N+c + 3] = a23; break;
                    case 12: C[(r+3)*N+c]     = a30; break;
                    case 13: C[(r+3)*N+c + 1] = a31; break;
                    case 14: C[(r+3)*N+c + 2] = a32; break;
                    case 15: C[(r+3)*N+c + 3] = a33; break;
                    case 16: C[(r+4)*N+c]     = a40; break;
                    case 17: C[(r+4)*N+c + 1] = a41; break;
                    case 18: C[(r+4)*N+c + 2] = a42; break;
                    case 19: C[(r+4)*N+c + 3] = a43; break;
                    case 20: C[(r+5)*N+c]     = a50; break;
                    case 21: C[(r+5)*N+c + 1] = a51; break;
                    case 22: C[(r+5)*N+c + 2] = a52; break;
                    case 23: C[(r+5)*N+c + 3] = a53; break;
                    case 24: C[(r+6)*N+c]     = a60; break;
                    case 25: C[(r+6)*N+c + 1] = a61; break;
                    case 26: C[(r+6)*N+c + 2] = a62; break;
                    case 27: C[(r+6)*N+c + 3] = a63; break;
                    case 28: C[(r+7)*N+c]     = a70; break;
                    case 29: C[(r+7)*N+c + 1] = a71; break;
                    case 30: C[(r+7)*N+c + 2] = a72; break;
                    case 31: C[(r+7)*N+c + 3] = a73; break;
                }
            }
        }
}

